// ---------------------------------------------------------------------------
// Prepare the supplier draft order.
//  - For each ordered item: use its exact supplier variant if mapped, else
//    search the supplier Shopify store by the BRAND-STRIPPED title.
//  - Build the Shopify draft_order body (line items + customer + address).
// Requires two n8n env vars (or swap for credentials):
//    SHOPIFY_STORE  = your-supplier.myshopify.com
//    SHOPIFY_TOKEN  = shpat_...  (Admin API access token)
// ---------------------------------------------------------------------------
const store = $env.SHOPIFY_STORE;
const token = $env.SHOPIFY_TOKEN;
const API = '2024-10';

const payload = $input.first().json.body || $input.first().json;
const items = payload.items || [];
const c = payload.customer || {};

// Words to remove when auto-building a search term. The item's own vendor is
// always stripped; extend this list with brands you carry.
const BRAND_STOPWORDS = ['rolex','gucci','nike','adidas','apple','samsung','original','genuine','brand'];

function cleanTitle(title, vendor) {
  let q = String(title || '').toLowerCase();
  if (vendor) q = q.split(String(vendor).toLowerCase()).join(' ');
  for (const w of BRAND_STOPWORDS) q = q.replace(new RegExp('\\b' + w + '\\b', 'gi'), ' ');
  return q.replace(/\s+/g, ' ').trim();
}

const gidToNumeric = (v) => (v == null ? null : String(v).split('/').pop());

const findVariant = async (term) => {
  const query = 'query($q:String!){products(first:1,query:$q){edges{node{title handle variants(first:1){edges{node{id title}}}}}}}';
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://${store}/admin/api/${API}/graphql.json`,
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' },
    body: { query, variables: { q: term } },
    json: true,
  });
  const edge = res && res.data && res.data.products && res.data.products.edges && res.data.products.edges[0];
  const v = edge && edge.node && edge.node.variants && edge.node.variants.edges && edge.node.variants.edges[0] && edge.node.variants.edges[0].node;
  if (!v) return null;
  return { variant_id: Number(gidToNumeric(v.id)), matchedTitle: edge.node.title };
};

const line_items = [];
const matches = [];
const unmatched = [];

for (const it of items) {
  let variantId = it.supplierVariantId ? gidToNumeric(it.supplierVariantId) : null;
  let matchedTitle = it.title;
  let mode = 'exact';
  if (!variantId) {
    const term = (it.supplierTitle && it.supplierTitle.trim()) || cleanTitle(it.title, it.vendor);
    const found = await findVariant(term);
    if (found) { variantId = found.variant_id; matchedTitle = found.matchedTitle; mode = 'search'; }
    else { unmatched.push({ title: it.title, term }); continue; }
  }
  line_items.push({ variant_id: Number(variantId), quantity: Number(it.quantity) || 1 });
  matches.push({ ordered: it.title, matched: matchedTitle, mode });
}

const nameParts = String(c.name || 'Customer').trim().split(/\s+/);
const firstName = nameParts.shift() || 'Customer';
const lastName = nameParts.join(' ') || '-';
const email = (c.email || '').trim();

const draft_order = {
  line_items,
  note: `Relayed from store order ${payload.orderNumber || ''}. ${c.note || ''}`.trim(),
  tags: `order-relay,${payload.orderNumber || ''}`,
  shipping_address: {
    first_name: firstName,
    last_name: lastName,
    address1: c.address || '',
    city: c.city || '',
    province: c.governorate || '',
    country: 'Egypt',
    phone: c.phone || '',
  },
};
if (email) draft_order.email = email;

return [{
  json: {
    orderNumber: payload.orderNumber || null,
    hasItems: line_items.length > 0,
    hasEmail: Boolean(email),
    email,
    matches,
    unmatched,
    body: { draft_order },
  },
}];
